// src/pages/Subscriptions.js
import React, { useEffect, useState } from "react";
import "../styles/subscriptions.css";

const BASE_URL = "http://127.0.0.1:8000";

function Subscriptions() {
  const [channels, setChannels] = useState([]);
  const [selectedChannel, setSelectedChannel] = useState(null);
  const [combinedContent, setCombinedContent] = useState([]);
  const [loadingChannels, setLoadingChannels] = useState(true);
  const [loadingContent, setLoadingContent] = useState(false);
  const [error, setError] = useState(null);
  const token = localStorage.getItem("token");

  // Завантажуємо канали + логування
  useEffect(() => {
    const fetchChannels = async () => {
      setLoadingChannels(true);
      setError(null);
      console.log("[Subscriptions] Fetching channels from", `${BASE_URL}/api/channels/`);
      try {
        const res = await fetch(`${BASE_URL}/api/channels/`, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        });

        if (!res.ok) {
          const text = await res.text().catch(() => "");
          console.error("[Subscriptions] channels fetch failed:", res.status, text);
          throw new Error(`HTTP ${res.status} ${res.statusText} ${text ? "- " + text : ""}`);
        }

        const data = await res.json();
        console.log("[Subscriptions] channels loaded:", data);
        setChannels(Array.isArray(data) ? data : data.results || []);
      } catch (err) {
        console.error("[Subscriptions] fetchChannels error:", err);
        setError("Помилка завантаження каналів: " + (err.message || "unknown"));
        setChannels([]);
      } finally {
        setLoadingChannels(false);
      }
    };

    fetchChannels();
  }, [token]);

  // Завантажуємо контент вибраного каналу (статті + опитування)
  const openChannel = async (channel) => {
    setSelectedChannel(channel);
    setCombinedContent([]);
    setError(null);
    setLoadingContent(true);

    const articlesUrl = `${BASE_URL}/api/channels/${channel.id}/articles/`;
    const pollsUrl = `${BASE_URL}/api/channels/${channel.id}/polls/`;
    console.log(`[Subscriptions] load content for channel ${channel.id}`, { articlesUrl, pollsUrl });

    try {
      const [aRes, pRes] = await Promise.all([
        fetch(articlesUrl, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }),
        fetch(pollsUrl, {
          headers: {
            "Content-Type": "application/json",
            ...(token && { Authorization: `Bearer ${token}` }),
          },
        }),
      ]);

      if (!aRes.ok) {
        const t = await aRes.text().catch(() => "");
        console.error("[Subscriptions] articles fetch failed", aRes.status, t);
        throw new Error("Не вдалося завантажити статті каналу: " + aRes.status);
      }
      if (!pRes.ok) {
        const t = await pRes.text().catch(() => "");
        console.error("[Subscriptions] polls fetch failed", pRes.status, t);
        throw new Error("Не вдалося завантажити опитування каналу: " + pRes.status);
      }

      const [articlesData, pollsData] = await Promise.all([aRes.json(), pRes.json()]);

      // Нормалізація: додаємо поле type і created_at (якщо немає - використаємо created_at або publish_date)
      const normArticles = (Array.isArray(articlesData) ? articlesData : articlesData.results || []).map(
        (a) => ({
          ...a,
          type: "article",
          created_at: a.publish_date || a.created_at || new Date().toISOString(),
        })
      );

      const normPolls = (Array.isArray(pollsData) ? pollsData : pollsData.results || []).map((p) => ({
        ...p,
        type: "poll",
        created_at: p.created_at || new Date().toISOString(),
      }));

      const merged = [...normArticles, ...normPolls].sort(
        (x, y) => new Date(y.created_at) - new Date(x.created_at)
      );

      console.log("[Subscriptions] merged content:", merged);
      setCombinedContent(merged);
    } catch (err) {
      console.error("[Subscriptions] openChannel error:", err);
      setError(err.message || "Помилка завантаження контенту");
      setCombinedContent([]);
    } finally {
      setLoadingContent(false);
    }
  };

  const handleVote = async (pollId, choiceId) => {
    setError(null);
    const url = `${BASE_URL}/api/polls/${pollId}/vote/${choiceId}/`;
    console.log("[Subscriptions] vote", { pollId, choiceId, url });
    try {
      const res = await fetch(url, {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          ...(token && { Authorization: `Bearer ${token}` }),
        },
      });

      if (!res.ok) {
        const txt = await res.text().catch(() => "");
        console.error("[Subscriptions] vote failed", res.status, txt);
        throw new Error(`Помилка голосування: ${res.status}`);
      }

      // Після успішного голосу оновимо локально голоси (щоб UI відобразив негайно)
      setCombinedContent((prev) =>
        prev.map((item) => {
          if (item.type !== "poll" || item.id !== pollId) return item;
          return {
            ...item,
            choices: item.choices.map((c) => (c.id === choiceId ? { ...c, votes: (c.votes || 0) + 1 } : c)),
          };
        })
      );
    } catch (err) {
      console.error("[Subscriptions] handleVote error:", err);
      setError(err.message || "Не вдалося відправити голос");
    }
  };

  return (
    <div className="subscriptions-container">
      <h2>Підписки</h2>

      {loadingChannels && <p>Завантаження каналів…</p>}
      {error && <p className="error">Помилка: {error}</p>}

      <div className="channel-list">
        {channels.map((ch) => (
          <button
            key={ch.id}
            className={`channel-btn ${selectedChannel?.id === ch.id ? "active" : ""}`}
            onClick={() => openChannel(ch)}
          >
            {ch.name || `Канал ${ch.id}`}
          </button>
        ))}
      </div>

      {selectedChannel && (
        <div className="channel-content">
          <h3>Контент каналу: {selectedChannel.name}</h3>
          {loadingContent && <p>Завантаження контенту…</p>}
          {!loadingContent && combinedContent.length === 0 && <p>Контент відсутній</p>}

          <div className="content-list">
            {combinedContent.map((item) =>
              item.type === "article" ? (
                <div key={`article-${item.id}`} className="article-card">
                  <h4>{item.title || "(без заголовка)"}</h4>
                  <p>{item.excerpt || item.content || "(без тексту)"}</p>
                  <small>Опубліковано: {new Date(item.created_at).toLocaleString()}</small>
                </div>
              ) : (
                <div key={`poll-${item.id}`} className="poll-card">
                  <h4>🗳️ {item.question}</h4>
                  <div className="poll-choices">
                    {item.choices && item.choices.length > 0 ? (
                      item.choices.map((c) => (
                        <div key={c.id} className="poll-choice">
                          <button className="vote-btn" onClick={() => handleVote(item.id, c.id)}>
                            Проголосувати
                          </button>
                          <span className="choice-text">
                            {c.text} — <b>{c.votes ?? 0}</b>
                          </span>
                        </div>
                      ))
                    ) : (
                      <p>Немає варіантів відповіді</p>
                    )}
                  </div>
                  <small>Створено: {new Date(item.created_at).toLocaleString()}</small>
                </div>
              )
            )}
          </div>
        </div>
      )}
    </div>
  );
}

export default Subscriptions;
